-- Enquiry discussions v1, 2026-10-12. No offers or rentals.
-- Read enquiry-discussions-guide.md first. Back up and pause app writers.
-- Default: DRY RUN. Change only apply_changes below to true to persist.
-- Times without offsets are interpreted as Singapore wall-clock time.
BEGIN;
SET LOCAL TIME ZONE 'Asia/Singapore';
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '60s';

CREATE TEMP TABLE seed_settings (apply_changes boolean NOT NULL) ON COMMIT DROP;
INSERT INTO seed_settings VALUES (false);

-- Short-lived locks prevent state changing between validation and insertion.
LOCK TABLE public.users, public.listings, public.rentals, public.chathistory,
           public.request, public.payment, public.reviews
    IN SHARE ROW EXCLUSIVE MODE;

CREATE TEMP TABLE seed_discussions ON COMMIT DROP AS
SELECT *
FROM jsonb_to_recordset($manifest$
