 viewing time.","listingid":null,"listing_name_snapshot":null,"listing_address_snapshot":null,"rentalid":null,"requestid":null,"existing_messageid":null}]}]
$manifest$::jsonb) AS d(
    listingid bigint, name text, location text, price bigint,
    ownerid bigint, owner_name text, tenantid bigint, tenant_name text,
    messages jsonb
);

CREATE TEMP TABLE seed_messages ON COMMIT DROP AS
SELECT d.listingid AS discussion_listingid, d.ownerid, d.tenantid, m.*
FROM seed_discussions d
CROSS JOIN LATERAL jsonb_to_recordset(d.messages) AS m(
    ordinal integer, date timestamp, senderid bigint, receiverid bigint,
    message text, listingid bigint, listing_name_snapshot text,
    listing_address_snapshot text, rentalid bigint, requestid bigint,
    existing_messageid bigint
);
ALTER TABLE seed_messages ADD PRIMARY KEY (discussion_listingid, ordinal);

CREATE TEMP VIEW seed_matches AS
SELECT s.discussion_listingid, s.ordinal, s.existing_messageid,
       count(c.messageid) AS matches
FROM seed_messages s
LEFT JOIN public.chathistory c
  ON c.senderid = s.senderid AND c.receiverid = s.receiverid
 AND c.date::timestamp = s.date AND c.message = s.message
 AND c.listingid IS NOT DISTINCT FROM s.listingid
 AND c.listing_name_snapshot IS NOT DISTINCT FROM s.listing_name_snapshot
 AND c.listing_address_snapshot IS NOT DISTINCT FROM s.listing_address_snapshot
 AND c.rentalid IS NULL AND c.requestid IS NULL
 AND (s.existing_messageid IS NULL OR c.messageid = s.existing_messageid)
GROUP BY s.discussion_listingid, s.ordinal, s.existing_messageid;

CREATE TEMP TABLE seed_result (
    outcome text, discussions integer, existing_messages integer,
    planned_new_messages integer, inserted_messages integer
) ON COMMIT DROP;

DO $seed$
DECLARE
    matching_new integer;
    inserted integer;
    bad_ids text;
    table_name text;
    signature text;
    initial_chat_count bigint;
BEGIN
    -- Fail closed if this manifest has been accidentally edited.
    IF (SELECT count(*) FROM seed_discussions) <> 35
       OR (SELECT count(DISTINCT listingid) FROM seed_discussions) <> 35
       OR (SELECT count(DISTINCT tenantid) FROM seed_discussions) <> 35
       OR (SELECT count(*) FROM seed_messages) <> 210
       OR EXISTS (SELECT 1 FROM seed_messages WHERE length(message) NOT BETWEEN 1 AND 255
                  OR senderid = receiverid OR rentalid IS NOT NULL OR requestid IS NOT NULL)
       OR EXISTS (
          SELECT 1 FROM seed_messages s JOIN seed_discussions d
          ON d.listingid = s.discussion_listingid
          WHERE s.senderid <> CASE WHEN ordinal % 2 = 1 THEN d.tenantid ELSE d.ownerid END
             OR s.receiverid <> CASE WHEN ordinal % 2 = 1 THEN d.ownerid ELSE d.tenantid END
             OR (ordinal = 1 AND (s.listingid IS DISTINCT FROM d.listingid
                 OR s.listing_name_snapshot IS DISTINCT FROM d.name
                 OR s.listing_address_snapshot IS DISTINCT FROM d.location))
             OR (ordinal <> 1 AND (s.listingid IS NOT NULL
                 OR s.listing_name_snapshot IS NOT NULL OR s.listing_address_snapshot IS NOT NULL))
       )
    THEN RAISE EXCEPTION 'Invalid discussion manifest; use the original reviewed file.';
    END IF;

    IF (SELECT count(*) FROM seed_matches WHERE existing_messageid = 209 AND matches = 1) <> 1
    THEN RAISE EXCEPTION 'Message 209 missing or changed. Export its current row; do not recreate or overwrite it.';
    END IF;
    IF EXISTS (SELECT 1 FROM seed_matches WHERE matches > 1)
    THEN RAISE EXCEPTION 'Duplicate matching messages already exist; inspect history before continuing.';
    END IF;
    SELECT count(*) INTO matching_new FROM seed_matches
    WHERE existing_messageid IS NULL AND matches = 1;
    IF matching_new = 209 THEN
        INSERT INTO seed_result VALUES ('ALREADY APPLIED: no changes', 35, 210, 0, 0);
        RETURN;
    END IF;
    IF matching_new <> 0 THEN
        RAISE EXCEPTION 'Partial batch detected (% of 209 new messages). Nothing inserted.', matching_new;
    END IF;

    SELECT string_agg(d.listingid::text, ', ' ORDER BY d.listingid)
    INTO bad_ids
    FROM seed_discussions d
    LEFT JOIN public.listings l ON l.listingid = d.listingid
    LEFT JOIN public.users o ON o.userid = d.ownerid
    LEFT JOIN public.users t ON t.userid = d.tenantid
    WHERE l.listingid IS NULL OR o.userid IS NULL OR t.userid IS NULL
       OR l.owneruserid IS DISTINCT FROM d.ownerid
       OR l.tenantuserid IS NOT NULL OR l.flagged IS DISTINCT FROM false
       OR o.flagged IS DISTINCT FROM 0 OR t.flagged IS DISTINCT FROM 0
       OR o.role::text IS DISTINCT FROM 'USER' OR t.role::text IS DISTINCT FROM 'USER'
       OR o.name IS DISTINCT FROM d.owner_name OR t.name IS DISTINCT FROM d.tenant_name
       OR l.name IS DISTINCT FROM d.name OR l.location IS DISTINCT FROM d.location
       OR l.price IS DISTINCT FROM d.price
       OR EXISTS (SELECT 1 FROM public.rentals r WHERE r.listingid = d.listingid
                  AND (r.status IS NULL OR lower(trim(r.status)) NOT IN ('terminated')));
    IF bad_ids IS NOT NULL THEN
        RAISE EXCEPTION 'Listing/participant drift or non-ended rental for listings: %. No changes.', bad_ids;
    END IF;

    SELECT string_agg(d.listingid::text, ', ' ORDER BY d.listingid)
    INTO bad_ids FROM seed_discussions d
    WHERE EXISTS (
        SELECT 1 FROM public.chathistory c
        WHERE ((c.senderid = d.ownerid AND c.receiverid = d.tenantid)
            OR (c.senderid = d.tenantid AND c.receiverid = d.ownerid))
          AND c.messageid <> 209
    );
    IF bad_ids IS NOT NULL THEN
        RAISE EXCEPTION 'Existing conversation needs review for listings: %. Export both directions for these pairs.', bad_ids;
    END IF;

    IF EXISTS (
        SELECT 1 FROM seed_messages s
        JOIN public.listings l ON l.listingid = s.discussion_listingid
        JOIN public.users o ON o.userid = s.ownerid
        JOIN public.users t ON t.userid = s.tenantid
        WHERE s.date > LOCALTIMESTAMP
           OR l.created_at IS NULL OR o.created_at IS NULL OR t.created_at IS NULL
           OR s.date <= l.created_at::timestamp
           OR s.date <= o.created_at::timestamp OR s.date <= t.created_at::timestamp
    ) THEN
        RAISE EXCEPTION 'Message dates conflict with creation times or current Singapore time. Review timezone and exports.';
    END IF;

    IF NOT (SELECT apply_changes FROM seed_settings) THEN
        INSERT INTO seed_result VALUES ('DRY RUN PASSED: no changes', 35, 1, 209, 0);
        RETURN;
    END IF;

    CREATE TEMP TABLE seed_original_chat ON COMMIT DROP AS
    SELECT messageid, to_jsonb(c) AS original FROM public.chathistory c;
    SELECT count(*) INTO initial_chat_count FROM seed_original_chat;
    CREATE TEMP TABLE seed_protected (relation_name text, fingerprint text) ON COMMIT DROP;
    FOREACH table_name IN ARRAY ARRAY['users','listings','rentals','request','payment','reviews']
    LOOP
        EXECUTE format(
            'SELECT md5(coalesce(string_agg(to_jsonb(t)::text, E''\n'' ORDER BY to_jsonb(t)::text), '''')) FROM public.%I t',
            table_name) INTO signature;
        INSERT INTO seed_protected VALUES (table_name, signature);
    END LOOP;

    INSERT INTO public.chathistory
        (date, message, receiverid, rentalid, requestid, senderid,
         listingid, listing_name_snapshot, listing_address_snapshot)
    SELECT date, message, receiverid, NULL, NULL, senderid,
           listingid, listing_name_snapshot, listing_address_snapshot
    FROM seed_messages WHERE existing_messageid IS NULL
    ORDER BY date, discussion_listingid, ordinal;
    GET DIAGNOSTICS inserted = ROW_COUNT;

    IF inserted <> 209
       OR (SELECT count(*) FROM seed_matches WHERE matches = 1) <> 210
       OR (SELECT count(*) FROM public.chathistory) <> initial_chat_count + 209
       OR EXISTS (
           SELECT 1 FROM seed_original_chat b LEFT JOIN public.chathistory c USING (messageid)
           WHERE b.original IS DISTINCT FROM to_jsonb(c)
       )
    THEN RAISE EXCEPTION 'Post-insert chat verification failed; rolling back this batch.';
    END IF;
    FOREACH table_name IN ARRAY ARRAY['users','listings','rentals','request','payment','reviews']
    LOOP
        EXECUTE format(
            'SELECT md5(coalesce(string_agg(to_jsonb(t)::text, E''\n'' ORDER BY to_jsonb(t)::text), '''')) FROM public.%I t',
            table_name) INTO signature;
        IF signature IS DISTINCT FROM (SELECT fingerprint FROM seed_protected WHERE relation_name = table_name)
        THEN RAISE EXCEPTION 'Protected table % changed; rolling back this batch.', table_name;
        END IF;
    END LOOP;
    INSERT INTO seed_result VALUES ('APPLIED', 35, 1, 209, inserted);
END
$seed$;

SELECT * FROM seed_result;
-- Per-discussion verification, also available by rerunning this file in dry-run mode.
SELECT d.listingid, d.ownerid, d.tenantid,
       count(*) FILTER (WHERE m.matches = 1) AS matched_messages,
       6 AS expected_messages
FROM seed_discussions d JOIN seed_matches m ON m.discussion_listingid = d.listingid
GROUP BY d.listingid, d.ownerid, d.tenantid ORDER BY d.listingid;
DROP VIEW seed_matches;
COMMIT;
